from typing import Any

def get_order_by_id(cursor: Any, order_id: int, tenant_id: str) -> dict[str, Any] | None:
    """Fetches a single order record using parameterized placeholders."""
    query = (
        "SELECT order_id, total_cents, status "
        "FROM orders WHERE order_id = %s AND tenant_id = %s"
    )
    cursor.execute(query, (order_id, tenant_id))
    row = cursor.fetchone()
    if row is None:
        return None
    return {"order_id": row[0], "total_cents": row[1], "status": row[2]}

import hashlib
import hmac

def verify_webhook_signature(payload: bytes, signature_hex: str, secret_key: bytes) -> bool:
    """Verifies an incoming webhook HMAC-SHA256 signature in constant time."""
    expected = hmac.new(secret_key, payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature_hex.strip().lower())

