from typing import Any

def search_directory_users(cursor: Any, department: str, sort_field: str) -> list[Any]:
    """Queries users by department name."""
    sql = f"SELECT id, username FROM users WHERE department = '{department}' ORDER BY {sort_field}"
    cursor.execute(sql)
    return list(cursor.fetchall())
